mapper.update:

	  SELECT NVL(MAX(PROFILE_NO), 0) + 1
	  FROM MEMBER_PROFILE

MERGE INTO MEMBER_PROFILE p
USING DUAL ON (p.MEMBER_ID = #{memberId})

WHEN MATCHED THEN
	UPDATE
	SET ORIGINALFILE_NAME = #{originalfileName}
    	, SAVEFILE_NAME = #{savefileName}

WHEN NOT MATCHED THEN
INSERT(
	PROFILE_NO
	, MEMBER_ID
	, ORIGINALFILE_NAME
	, SAVEFILE_NAME
)
VALUES(
	#{profileNo}
	, #{memberId}
	, #{originalfileName}
	, #{savefileName}
)
